// Meter is the default Flipt-wide otel metric Meter.
var Meter metric.Meter

func init() {
	// a no-op meter provider is registered on initialization to ensure that
	// a meter is always available to Flipt packages.
	// the exporter (and therefore the provider) can be configured and replaced
	// at startup using GetExporter.
	provider := noopmetric.NewMeterProvider()
	otel.SetMeterProvider(provider)

	Meter = provider.Meter("github.com/flipt-io/flipt")
}

var (
	metricExpOnce sync.Once
	metricExp     sdkmetric.Reader
	metricExpFunc func(context.Context) error
	metricExpErr  error
)

// GetExporter constructs and configures the metric exporter based on the chosen
// exporter using the provided config.
func GetExporter(ctx context.Context, cfg *config.MetricsConfig) (sdkmetric.Reader, func(context.Context) error, error) {
	metricExpOnce.Do(func() {
		// initialize the shutdown func to a no-op, so it's always
		// safe to invoke it after this point
		metricExpFunc = func(context.Context) error { return nil }

		switch cfg.Exporter {
		case config.MetricsPrometheus:
			// exporter registers itself on the prom client DefaultRegistrar
			exporter, err := prometheus.New()
			if err != nil {
				metricExpErr = err
				return
			}

			metricExp = exporter
		case config.MetricsOTLP:
			u, err := url.Parse(cfg.OTLP.Endpoint)
			if err != nil {
				metricExpErr = fmt.Errorf("parsing url for metrics otlp exporter: %w", err)
				return
			}

			var exp sdkmetric.Exporter
			switch u.Scheme {
			case "http", "https":
				exp, err = otlpmetrichttp.New(ctx,
					otlpmetrichttp.WithEndpoint(u.Host+u.Path),
					otlpmetrichttp.WithHeaders(cfg.OTLP.Headers),
				)
			case "grpc":
				// TODO: support TLS
				exp, err = otlpmetricgrpc.New(ctx,
					otlpmetricgrpc.WithEndpoint(u.Host+u.Path),
					otlpmetricgrpc.WithHeaders(cfg.OTLP.Headers),
					otlpmetricgrpc.WithInsecure(),
				)
			default:
				// because of url parsing ambiguity, we'll assume that the endpoint is a host:port with no scheme
				exp, err = otlpmetricgrpc.New(ctx,
					otlpmetricgrpc.WithEndpoint(cfg.OTLP.Endpoint),
					otlpmetricgrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlpmetricgrpc.WithInsecure(),
				)
			}

			if err != nil {
				metricExpErr = fmt.Errorf("creating metrics otlp exporter: %w", err)
				return
			}

			metricExp = sdkmetric.NewPeriodicReader(exp)
			metricExpFunc = func(ctx context.Context) error {
				return exp.Shutdown(ctx)
			}
		default:
			metricExpErr = fmt.Errorf("unsupported metrics exporter: %s", cfg.Exporter)
			return
		}
	})

	return metricExp, metricExpFunc, metricExpErr
}
